NotaryLaws.register({"id":"konst","abbr":"Конституция","title":{"bg":"Конституция на Република България (извадка)","en":"Constitution of the Republic of Bulgaria (extract)"},"group":"civil","source":"https://lex.bg/laws/ldoc/521957377","retrieved":"2026-10-21","partial":true,"articles":15,"inForce":"В сила от 13.07.1991 г.","published":"Обн. ДВ. бр.56 от 13 Юли 1991г.","lastChange":"изм. ДВ. бр.66 от 6 Август 2024г.","items":[{"k":"h","t":"Глава първа. ОСНОВНИ НАЧАЛА"},{"k":"a","n":"4","p":["Чл. 4. (1) Република България е правова държава. Тя се управлява според Конституцията и законите на страната.","(2) Република България гарантира живота, достойнството и правата на личността и създава условия за свободно развитие на човека и на гражданското общество.","(3) (Нова - ДВ, бр. 18 от 2005 г.) Република България участва в изграждането и развитието на Европейския съюз."]},{"k":"a","n":"5","p":["Чл. 5. (1) Конституцията е върховен закон и другите закони не могат да и противоречат.","(2) Разпоредбите на Конституцията имат непосредствено действие.","(3) Никой не може да бъде осъден за действие или бездействие, което не е било обявено от закона за престъпление към момента на извършването му.","(4) Международните договори, ратифицирани по конституционен ред, обнародвани и влезли в сила за Република България, са част от вътрешното право на страната. Те имат предимство пред тези норми на вътрешното законодателство, които им противоречат.","(5) Всички нормативни актове се публикуват. Те влизат в сила три дни след обнародването им, освен когато в тях е определен друг срок."]},{"k":"a","n":"17","p":["Чл. 17. (1) Правото на собственост и на наследяване се гарантира и защитава от закона.","(2) Собствеността е частна и публична.","(3) Частната собственост е неприкосновена.","(4) Режимът на обектите на държавната и общинската собственост се определя със закон.","(5) Принудително отчуждаване на собственост за държавни и общински нужди може да става само въз основа на закон, при условие че тези нужди не могат да бъдат задоволени по друг начин и след предварително и равностойно обезщетение."]},{"k":"a","n":"18","p":["Чл. 18. (1) Подземните богатства, крайбрежната плажна ивица, републиканските пътища, както и водите, горите и парковете с национално значение, природните и археологическите резервати, определени със закон, са изключителна държавна собственост.","(2) Държавата осъществява суверенни права върху континенталния шелф и в изключителната икономическа зона за проучване, разработване, използване, опазване и стопанисване на биологичните, минералните и енергийните ресурси на тези морски пространства.","(3) Държавата осъществява суверенни права върху радиочестотния спектър и позициите на геостационарната орбита, определени за Република България с международни споразумения.","(4) Със закон може да се установява държавен монопол върху железопътния транспорт, националните пощенски и далекосъобщителни мрежи, използването на ядрена енергия, производството на радиоактивни продукти, оръжие, взривни и биологично силно действащи вещества.","(5) Условията и редът, при които държавата предоставя концесии за обектите и разрешения за дейностите по предходните алинеи, се уреждат със закон.","(6) Държавните имоти се стопанисват и управляват в интерес на гражданите и на обществото."]},{"k":"a","n":"19","p":["Чл. 19. (1) Икономиката на Република България се основава на свободната стопанска инициатива.","(2) Законът създава и гарантира на всички граждани и юридически лица еднакви правни условия за стопанска дейност, като предотвратява злоупотребата с монополизма, нелоялната конкуренция и защитава потребителя.","(3) Инвестициите и стопанската дейност на български и чуждестранни граждани и юридически лица се закрилят от закона.","(4) Законът създава условия за коопериране и други форми на сдружаване на гражданите и юридическите лица за постигане на стопански и социален напредък."]},{"k":"a","n":"20","p":["Чл. 20. Държавата създава условия за балансирано развитие на отделните райони на страната и подпомага териториалните органи и дейности чрез финансовата, кредитната и инвестиционната политика."]},{"k":"a","n":"21","p":["Чл. 21. (1) Земята е основно национално богатство, което се ползва от особената закрила на държавата и обществото.","(2) Обработваемата земя се използва само за земеделски цели. Промяна на нейното предназначение се допуска по изключение при доказана нужда и при условия и по ред, определени със закон."]},{"k":"a","n":"22","p":["Чл. 22. (Изм. - ДВ, бр. 18 от 2005 г., в сила от 01.01.2007 г. (*)) (1) Чужденци и чуждестранни юридически лица могат да придобиват право на собственост върху земя при условията, произтичащи от присъединяването на Република България към Европейския съюз или по силата на международен договор, ратифициран, обнародван и влязъл в сила за Република България, както и чрез наследяване по закон.","(2) Законът за ратифициране на международен договор по ал. 1 се приема с мнозинство две трети от всички народни представители.","(3) Режимът на земята се определя със закон."]},{"k":"h","t":"Глава шеста. СЪДЕБНА ВЛАСТ"},{"k":"a","n":"117","p":["Чл. 117. (1) Съдебната власт защитава правата и законните интереси на гражданите, юридическите лица и държавата.","(2) (Изм. и доп. - ДВ, бр. 106 от 2023 г.) Съдебната власт е независима и неин основен носител е съдът. Прокуратурата и следствените органи са в системата на съдебната власт. При осъществяване на своите функции съдиите, съдебните заседатели, прокурорите и следователите се подчиняват само на закона.","(3) Съдебната власт има самостоятелен бюджет."]},{"k":"a","n":"118","p":["Чл. 118. Правосъдието се осъществява в името на народа."]},{"k":"a","n":"119","p":["Чл. 119. (1) Правораздаването се осъществява от Върховния касационен съд, Върховния административен съд, апелативни, окръжни, военни и районни съдилища.","(2) Със закон могат да се създават и специализирани съдилища.","(3) Извънредни съдилища не се допускат."]},{"k":"a","n":"120","p":["Чл. 120. (1) Съдилищата осъществяват контрол за законност на актове и действия на административните органи.","(2) Гражданите и юридическите лица могат да обжалват всички административни актове, които ги засягат, освен изрично посочените със закон."]},{"k":"a","n":"121","p":["Чл. 121. (1) Съдилищата осигуряват равенство и условия за състезателност на страните в съдебния процес.","(2) Производството по делата осигурява установяването на истината.","(3) Разглеждането на делата във всички съдилища е публично, освен когато законът предвижда друго.","(4) Актовете на правораздаването се мотивират."]},{"k":"a","n":"122","p":["Чл. 122. (1) Гражданите и юридическите лица имат право на защита във всички стадии на процеса.","(2) Редът за упражняване правото на защита се определя със закон."]},{"k":"a","n":"134","p":["Чл. 134. (1) Адвокатурата е свободна, независима и самоуправляваща се. Тя подпомага гражданите и юридическите лица при защитата на техните права и законни интереси.","(2) Организацията и редът на дейността на адвокатурата се уреждат със закон."]}]});
